import{_ as i,l as n,o as a,c as l,v as r,p as s,x as o,d as E,i as p,S as B}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"Brouwer 不动点","description":"","frontmatter":{"title":"Brouwer 不动点","date":"2026-09-10T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/brouwer-fixed-point.md","filePath":"econ/brouwer-fixed-point.md","lastUpdated":1789023840000}'),u={name:"econ/brouwer-fixed-point.md"};function d(c,e,h,f,A,_){const t=n("Mermaid");return a(),l("div",null,[e[1]||(e[1]=r('<h1 id="brouwer-不动点" tabindex="-1">Brouwer 不动点 <a class="header-anchor" href="#brouwer-不动点" aria-label="Permalink to &quot;Brouwer 不动点&quot;">​</a></h1><div class="epigraph"><p>紧凸集上的连续自映射必有一点留在原地；超额需求归一化之后，出清是这样一点。</p><footer>—— 据 Debreu, Theory of Value, 1959；Mas-Colell, Whinston and Green 第 17 章与数学附录整理</footer></div><p>上一课<a href="/econ/contraction-mapping">压缩映射</a>给出唯一不动点与算法。超额需求、最优反应（单值时）通常只有连续性与紧凸值域，没有 \\(\\beta\\lt 1\\)。缺口是存在性，不是唯一、不是迭代。Brouwer：紧凸 \\(C\\subset\\mathbb{R}^n\\)，\\(f:C\\to C\\) 连续，则存在 \\(x=f(x)\\)。Kakutani 把 \\(f\\) 换成对应，下一课再补。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单纯形 \\(\\Delta^{n-1}=\\{p\\ge 0:\\sum p_i=1\\}\\) 紧凸。把超额需求 \\(z(p)\\) 改造成 \\(f(p)\\propto p+\\max\\{z(p),0\\}\\) 一类的连续自映射（Walras 定律帮助像仍在单纯形上），不动点满足 \\(z(p^*)\\le 0\\) 且对 \\(p_i^*\\gt 0\\) 有 \\(z_i=0\\)。这是<a href="/econ/ge-existence">存在性与不动点</a>的骨架。本课不把 Debreu 的论证写完，只把 Brouwer 的假设与结论钉死：连续、紧、凸、自映射，四件缺一不可。</p><p>博弈里纯策略最优反应若单值连续，纳什就是 Brouwer。最优反应多半集值，要 Kakutani；有限博弈混合策略单纯形上的期望收益对混合概率线性，最佳反应凸值上半连续，那是后两课。本课先承认：单值连续已经够用 Brouwer。</p><h3 id="有不动点不是可算出来" tabindex="-1">有不动点不是可算出来 <a class="header-anchor" href="#有不动点不是可算出来" aria-label="Permalink to &quot;有不动点不是可算出来&quot;">​</a></h3><p>Brouwer 是纯存在。没有模 \\(\\beta\\)，Picard \\(x_{n+1}=f(x_n)\\) 可以旋转不收敛（圆周旋转没有不动点——但圆周不是凸的；凸里也可以有很糟的连续映射让朴素迭代失败）。计算一般均衡要 Scarf 算法、同伦，不在主干。不要把「存在」读成「市场会走到」。试错稳定性是<a href="/econ/uniqueness-tatonnement">唯一性与试错</a>的缺口。</p><p><span class="marginnote">凸不能丢：把圆环当定义域，旋转映射连续、紧，没有不动点。紧不能丢：\\(\\mathbb{R}\\) 上 \\(f(x)=x+1\\) 连续无不动点。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>有限维陈述足够主干。证明可以走：维数 1 是介值定理；\\(n\\) 维用单纯逼近或度理论，本课不证。要用时检查：(i) 定义域紧凸；(ii) \\(f\\) 连续；(iii) \\(f\\) 把定义域送进自身。价格单纯形上构造 \\(f\\) 时，(iii) 最容易写错：没有 Walras 定律或免费处置，像可能飞出 \\(\\Delta\\)。</p><p>唯一性要另加：总替代、毛替代、对角占优一类条件。SMD 定理说超额需求在正则条件下几乎任意，Brouwer 管存在，不管漂亮。后课<a href="/econ/smd-excess-demand">Sonnenschein–Mantel–Debreu</a>会讲这条边界；本课不要把存在说成「均衡很好」。</p>',12)),(a(),s(B,null,{default:o(()=>[p(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E7%B4%A7%E5%87%B8%E9%9B%86%20C%22%5D%20--%3E%20F%5B%22%E8%BF%9E%E7%BB%AD%20f%20%E4%BB%8E%20C%20%E5%88%B0%20C%22%5D%0A%20%20F%20--%3E%20FP%5B%22%E5%AD%98%E5%9C%A8%20x%20%E7%AD%89%E4%BA%8E%20f(x)%22%5D%0A%20%20FP%20--%3E%20GE%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%B6%85%E9%A2%9D%E9%9C%80%E6%B1%82%E5%87%BA%E6%B8%85%22%5D%0A%20%20FP%20--%3E%20NASH%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%8D%95%E5%80%BC%E6%9C%80%E4%BC%98%E5%8F%8D%E5%BA%94%E7%9A%84%E7%BA%B3%E4%BB%80%22%5D%0A%20%20COMP%5B%22%E5%8E%8B%E7%BC%A9%22%5D%20--%3E%20UNIQ%5B%22%E5%94%AF%E4%B8%80%E4%B8%94%E5%8F%AF%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20F%20--%3E%20NOTU%5B%22%E4%B8%80%E8%88%AC%E4%B8%8D%E5%94%AF%E4%B8%80%E3%80%81%E4%B8%8D%E7%BB%99%E7%AE%97%E6%B3%95%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[E(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>连续像不能「整块挪开」而不留下定点：否则可以把像与点之间的射线反推到边界，造出边界上无不动点的连续自映射，与低维事实矛盾。凸保证射线留在集合内；紧保证极限点还在。经济学翻译：价格在单纯形上连续调整规则若总把价格送到单纯形，就至少有一个「不再需要调整」的点。规则不必是真实的市场过程，只是存在性证明里的辅助映射。</p><p>与压缩的分工：折扣动态规划要唯一值函数、要算法，走 Banach；均衡与纳什常常多解，先走 Brouwer/Kakutani 保住非空，再另文讨论选择与稳定。</p><p><span class="marginnote">无穷维要 Schauder：紧凸、连续、像相对紧。宏观函数空间上的均衡有时走这条；主干有限商品仍用 Brouwer。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不在本课证 Brouwer，不写代数拓扑。不把不动点等同于瓦尔拉斯均衡的全部假设（偏好连续凸、生产凸、生存性都还在微观主干）。下一课把连续函数换成上半连续凸值对应——需求集值时必须换。</p><p>后课默认：单纯形上的连续自映射有不动点；单值连续最优反应有纳什；超额需求的存在性证明会构造这样一个 \\(f\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>紧凸上连续自映射必有不动点；缺紧、缺凸、缺连续都会反例。</li><li>存在不是唯一，也不是算法，更不是动态收敛。</li><li>均衡存在把超额需求改造成单纯形上的 \\(f\\)。</li><li>压缩更强：唯一加 Picard；Brouwer 更贴均衡。</li><li>下一课：<a href="/econ/kakutani-fixed-point">Kakutani 不动点</a>。</li><li>出处：Debreu, <em>Theory of Value</em>；MWG 第 17 章。</li></ul>',9))])}const x=i(u,[["render",d]]);export{b as __pageData,x as default};
